def define(tab, col):
    for d in ({"Companies": COMPANIES, "Near-miss": COMPANIES, "Buildings": BUILDINGS, "Coworking": COWORKING,
               "Retailers": RETAILERS, "Route": ROUTE, "Walk": WALK}[tab], COMMON):
        if col in d:
            return d[col]
    return ""
